Bash("F:\\A-War-Without-Victory\\_tmp_analyze.ts" << 'SCRIPT'
const fs = require\('fs'\);
const data = JSON.parse\(fs.readFileSync\('data/source/oob_brigades.json','utf8'\)\);
const brigades = data.brigades;

const stats: any = {};
for \(const b of brigades\) {
  const key = b.faction;
  if \(!stats[key]\) stats[key] = { total: 0, t0: 0, mandatory: 0, byCorps: {}, earlyBrigades: [] };
  stats[key].total++;
  if \(b.available_from === 0\) stats[key].t0++;
  if \(b.mandatory\) stats[key].mandatory++;

  const corps = b.subordinate_to || 'none';
  if \(!stats[key].byCorps[corps]\) stats[key].byCorps[corps] = { total: 0, t0: 0 };
  stats[key].byCorps[corps].total++;
  if \(b.available_from === 0\) stats[key].byCorps[corps].t0++;

  if \(b.available_from <= 4 && b.mandatory\) {
    stats[key].earlyBrigades.push\({ id: b.id, name: b.name, home: b.home_mun, corps: b.subordinate_to, avail: b.available_from, equip: b.default_equipment_class }\);
  }
}

for \(const [faction, s] of Object.entries\(stats\) as any\) {
  console.log\('=== ' + faction + ' ==='\);
  console.log\('Total:', s.total, '| Turn-0:', s.t0, '| Mandatory:', s.mandatory\);
  console.log\('By corps \(total / turn-0\):'\);
  for \(const [corps, c] of Object.entries\(s.byCorps\).sort\(\) as any\) {
    console.log\('  ' + corps + ':', c.total + ' / ' + c.t0\);
  }
  console.log\('Early mandatory brigades \(avail<=4\):'\);
  for \(const b of s.earlyBrigades\) {
    console.log\('  ' + b.id + ' | ' + b.name + ' | ' + b.home + ' | ' + b.corps + ' | T' + b.avail + ' | ' + b.equip\);
  }
  console.log\(\);
}
