#!/usr/bin/env node
/**
 * _check_gaps.mjs
 *
 * Compares operational_settlements.geojson \(clustered\) against
 * settlements_wgs84_1990.geojson \(original canonical\) to detect
 * area gaps, bounding-box divergence, and winding-direction errors.
 *
 * Usage:  node scripts/_check_gaps.mjs
 */

import { readFileSync } from "node:fs";
import { resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const require = createRequire\(import.meta.url\);
const turf = require\("@turf/turf"\);

const __dirname = dirname\(fileURLToPath\(import.meta.url\)\);
const ROOT = resolve\(__dirname, ".."\);

// ── Paths ──────────────────────────────────────────────────────────────────
const OPERATIONAL_PATH = resolve\(
  ROOT,
  "data/derived/operational/operational_settlements.geojson"
\);
const ORIGINAL_PATH = resolve\(
  ROOT,
  "data/derived/settlements_wgs84_1990.geojson"
\);

// ── Helpers ────────────────────────────────────────────────────────────────

/**
 * Signed area of a ring in raw coordinate space \(lon/lat\).
 * Positive = CCW \(correct GeoJSON outer ring\), Negative = CW \(wrong\).
 *
 * Uses the shoelace formula on [lon, lat] pairs.
 */
function signedRingArea\(ring\) {
  let sum = 0;
  for \(let i = 0, n = ring.length - 1; i < n; i++\) {
    const [x1, y1] = ring[i];
    const [x2, y2] = ring[i + 1];
    sum += \(x2 - x1\) * \(y2 + y1\);
  }
  return sum; // negative => CCW \(correct outer ring in lon/lat\), positive => CW \(wrong\)
}

/**
 * Returns true when the outer ring is wound CW \(wrong for GeoJSON outer rings\).
 * GeoJSON spec \(RFC 7946\): outer rings MUST be CCW.
 * In lon/lat coordinate space the shoelace formula gives a negative value for CCW.
 */
function isOuterRingCW\(ring\) {
  return signedRingArea\(ring\) > 0; // positive signed area => CW => wrong
}

function unionBBox\(a, b\) {
  if \(!a\) return b;
  return [
    Math.min\(a[0], b[0]\),
    Math.min\(a[1], b[1]\),
    Math.max\(a[2], b[2]\),
    Math.max\(a[3], b[3]\),
  ];
}

function bboxArea\(bb\) {
  // Approximate area of a lon/lat bbox in m^2 via turf
  const poly = turf.bboxPolygon\(bb\);
  return turf.area\(poly\);
}

function fmt\(n\) {
  return n.toLocaleString\("en-US", { maximumFractionDigits: 2 }\);
}

function fmtKm2\(m2\) {
  return fmt\(m2 / 1e6\) + " km^2";
}

// ── Load data ──────────────────────────────────────────────────────────────
console.log\("Loading GeoJSON files...\\n"\);

const opGeo = JSON.parse\(readFileSync\(OPERATIONAL_PATH, "utf8"\)\);
const origGeo = JSON.parse\(readFileSync\(ORIGINAL_PATH, "utf8"\)\);

// ── 1. Feature counts ─────────────────────────────────────────────────────
console.log\("==================================================================="\);
console.log\("  1. FEATURE COUNTS"\);
console.log\("==================================================================="\);
console.log\(`  Original  \(settlements_wgs84_1990\):   ${origGeo.features.length}`\);
console.log\(`  Operational \(operational_settlements\): ${opGeo.features.length}`\);
console.log\(\);

// ── 2. Total area ──────────────────────────────────────────────────────────
console.log\("==================================================================="\);
console.log\("  2. TOTAL AREA \(turf.area, geodesic m^2\)"\);
console.log\("==================================================================="\);

let origTotalArea = 0;
let origBBox = null;
for \(const f of origGeo.features\) {
  origTotalArea += turf.area\(f\);
  const bb = turf.bbox\(f\);
  origBBox = unionBBox\(origBBox, bb\);
}

let opTotalArea = 0;
let opBBox = null;
for \(const f of opGeo.features\) {
  opTotalArea += turf.area\(f\);
  const bb = turf.bbox\(f\);
  opBBox = unionBBox\(opBBox, bb\);
}

console.log\(`  Original total area:    ${fmtKm2\(origTotalArea\)}`\);
console.log\(`  Operational total area: ${fmtKm2\(opTotalArea\)}`\);
console.log\(\);

// ── 3. Area difference ────────────────────────────────────────────────────
console.log\("==================================================================="\);
console.log\("  3. AREA DIFFERENCE"\);
console.log\("==================================================================="\);

const areaDiff = origTotalArea - opTotalArea;
const areaDiffPct = \(areaDiff / origTotalArea\) * 100;
console.log\(`  Difference \(orig - op\): ${fmtKm2\(areaDiff\)}`\);
console.log\(`  As percentage of orig:  ${fmt\(areaDiffPct\)}%`\);
if \(areaDiff > 0\) {
  console.log\("  -> Operational has LESS area than original \(gaps exist\)."\);
} else if \(areaDiff < 0\) {
  console.log\("  -> Operational has MORE area than original \(overlaps or expansion\)."\);
} else {
  console.log\("  -> Areas are identical."\);
}
console.log\(\);

// ── 4. Bounding box union ──────────────────────────────────────────────────
console.log\("==================================================================="\);
console.log\("  4. BOUNDING BOX UNION"\);
console.log\("==================================================================="\);
console.log\(
  `  Original bbox:    [${origBBox.map\(\(v\) => v.toFixed\(6\)\).join\(", "\)}]`
\);
console.log\(
  `  Operational bbox: [${opBBox.map\(\(v\) => v.toFixed\(6\)\).join\(", "\)}]`
\);
console.log\(
  `  Original bbox area:    ${fmtKm2\(bboxArea\(origBBox\)\)}`
\);
console.log\(
  `  Operational bbox area: ${fmtKm2\(bboxArea\(opBBox\)\)}`
\);

const bboxMatch =
  origBBox[0] === opBBox[0] &&
  origBBox[1] === opBBox[1] &&
  origBBox[2] === opBBox[2] &&
  origBBox[3] === opBBox[3];
console.log\(
  `  BBox exact match: ${bboxMatch ? "YES" : "NO \(extents differ\)"}`
\);
console.log\(\);

// ── 5. Winding direction audit ─────────────────────────────────────────────
console.log\("==================================================================="\);
console.log\("  5. WINDING DIRECTION AUDIT \(operational GeoJSON\)"\);
console.log\("==================================================================="\);

const cwFeatures = [];
for \(const f of opGeo.features\) {
  const geom = f.geometry;
  if \(geom.type === "Polygon"\) {
    const outerRing = geom.coordinates[0];
    if \(isOuterRingCW\(outerRing\)\) {
      cwFeatures.push\({
        osid: f.properties.osid || f.properties.sid || "unknown",
        name: f.properties.settlement_name || "",
        signedArea: signedRingArea\(outerRing\),
        vertexCount: outerRing.length,
      }\);
    }
  } else if \(geom.type === "MultiPolygon"\) {
    for \(let pi = 0; pi < geom.coordinates.length; pi++\) {
      const outerRing = geom.coordinates[pi][0];
      if \(isOuterRingCW\(outerRing\)\) {
        cwFeatures.push\({
          osid:
            \(f.properties.osid || f.properties.sid || "unknown"\) +
            `[part ${pi}]`,
          name: f.properties.settlement_name || "",
          signedArea: signedRingArea\(outerRing\),
          vertexCount: outerRing.length,
        }\);
      }
    }
  }
}

console.log\(
  `  Total operational features checked: ${opGeo.features.length}`
\);
console.log\(
  `  Features with CW outer ring \(WRONG\): ${cwFeatures.length}`
\);

if \(cwFeatures.length > 0\) {
  console.log\(\);
  console.log\("  CW-wound features \(first 20\):"\);
  for \(const cw of cwFeatures.slice\(0, 20\)\) {
    console.log\(
      `    - ${cw.osid} "${cw.name}" \(signedArea=${cw.signedArea.toFixed\(8\)}, vertices=${cw.vertexCount}\)`
    \);
  }
  if \(cwFeatures.length > 20\) {
    console.log\(`    ... and ${cwFeatures.length - 20} more`\);
  }
} else {
  console.log\("  -> All outer rings are CCW \(correct GeoJSON winding\)."\);
}
console.log\(\);

// ── 6. Specific check: op:banja_luka:pervan_gornji ─────────────────────────
console.log\("==================================================================="\);
console.log\("  6. SPECIFIC CHECK: op:banja_luka:pervan_gornji"\);
console.log\("==================================================================="\);

const pervanFeature = opGeo.features.find\(
  \(f\) => f.properties.osid === "op:banja_luka:pervan_gornji"
\);

if \(!pervanFeature\) {
  console.log\("  Feature NOT FOUND in operational GeoJSON."\);
} else {
  const geom = pervanFeature.geometry;
  console.log\(`  Geometry type: ${geom.type}`\);
  console.log\(`  Properties: ${JSON.stringify\(pervanFeature.properties, null, 2\)}`\);

  if \(geom.type === "Polygon"\) {
    const outerRing = geom.coordinates[0];
    const sa = signedRingArea\(outerRing\);
    const isCW = sa > 0;
    const geodesicArea = turf.area\(pervanFeature\);

    console.log\(`  Outer ring vertices: ${outerRing.length}`\);
    console.log\(`  Signed area \(shoelace, lon/lat\): ${sa.toFixed\(10\)}`\);
    console.log\(`  Winding: ${isCW ? "CW \(WRONG for outer ring\)" : "CCW \(correct for outer ring\)"}`\);
    console.log\(`  Geodesic area \(turf\): ${fmtKm2\(geodesicArea\)}`\);

    // Also check holes
    if \(geom.coordinates.length > 1\) {
      console.log\(`  Holes: ${geom.coordinates.length - 1}`\);
      for \(let hi = 1; hi < geom.coordinates.length; hi++\) {
        const holeSA = signedRingArea\(geom.coordinates[hi]\);
        console.log\(
          `    Hole ${hi}: signed=${holeSA.toFixed\(10\)}, winding=${holeSA > 0 ? "CW \(correct for hole\)" : "CCW \(WRONG for hole\)"}`
        \);
      }
    } else {
      console.log\("  Holes: none"\);
    }

    // Check with turf.booleanClockwise for cross-reference
    console.log\(
      `  turf.booleanClockwise\(outerRing\): ${turf.booleanClockwise\(turf.lineString\(outerRing\)\)}`
    \);
